import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import Papa from 'papaparse'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { expensiveRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { formatCurrency } from '@/lib/utils'

const ExportSchema = z.object({
  ids: z.string().optional(), // comma-separated UUIDs; if omitted, exports all active
})

/**
 * Prevents CSV formula injection (CWE-1236).
 * Excel, Google Sheets, and LibreOffice Calc treat cell values starting with
 * =, +, -, @, \t, or \r as formulas. Prefixing with a single-quote forces
 * spreadsheet apps to treat the value as literal text.
 */
export function escapeCsvCell(value: unknown): string {
  const s = value == null ? '' : String(value)
  return /^[=+\-@\t\r]/.test(s) ? `'${s}` : s
}

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await expensiveRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const parsed = ExportSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) return NextResponse.json({ error: 'Invalid params' }, { status: 400 })

  const { ids } = parsed.data

  try {
    const supabase = await createClient()

    let query = supabase
      .from('clients')
      .select(
        'id, first_name, last_name, email, phone, date_of_birth, source, tags, total_spent_cents, total_sessions, no_show_count, last_visit_at, preferred_contact, created_at'
      )
      .eq('studio_id', authUser.studioId)
      .is('archived_at', null)
      .order('last_visit_at', { ascending: false, nullsFirst: false })

    if (ids) {
      const idArray = ids.split(',').filter(Boolean)
      query = query.in('id', idArray)
    }

    const { data, error } = await query

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'client export failed')
      return NextResponse.json({ error: 'Failed to export clients' }, { status: 500 })
    }

    const rows = (data ?? []).map((c) => {
      // escapeCsvCell applied to every user-controlled string field to prevent
      // formula injection when the CSV is opened in Excel / Google Sheets.
      const row: Record<string, string | number> = {
        'First Name': escapeCsvCell(c.first_name),
        'Last Name': escapeCsvCell(c.last_name ?? ''),
        'Email': escapeCsvCell(c.email ?? ''),
        'Phone': escapeCsvCell(c.phone ?? ''),
        'Date of Birth': escapeCsvCell(c.date_of_birth ?? ''),
        'Source': escapeCsvCell(c.source ?? ''),
        'Tags': escapeCsvCell((c.tags ?? []).join(', ')),
        'Total Spent': formatCurrency(c.total_spent_cents),
        'Total Sessions': c.total_sessions,
        'No-Shows': c.no_show_count,
        'Last Visit': escapeCsvCell(c.last_visit_at ?? ''),
        'Preferred Contact': escapeCsvCell(c.preferred_contact ?? ''),
        'Member Since': escapeCsvCell(c.created_at),
      }
      return row
    })

    const csv = Papa.unparse(rows)

    return new NextResponse(csv, {
      status: 200,
      headers: {
        'Content-Type': 'text/csv; charset=utf-8',
        'Content-Disposition': `attachment; filename="clients-${new Date().toISOString().split('T')[0]}.csv"`,
      },
    })
  } catch (err) {
    logger.error({ err }, 'client export unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const ListNotesSchema = z.object({
  client_id: z.string().uuid(),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(50).default(20),
})

const CreateNoteSchema = z.object({
  client_id: z.string().uuid(),
  category: z.enum(['general', 'medical', 'allergies', 'skin', 'emergency_contact', 'aftercare', 'preferences', 'artist_notes']).default('general'),
  body: z.string().min(2, 'Note must be at least 2 characters').max(10000),
  is_pinned: z.boolean().default(false),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const parsed = ListNotesSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  const { client_id, page, per_page } = parsed.data
  const from = (page - 1) * per_page
  const to = from + per_page - 1

  try {
    const supabase = await createClient()

    const { data, error, count } = await supabase
      .from('client_notes')
      .select('*, profiles:author_id(full_name, avatar_url)', { count: 'exact' })
      .eq('client_id', client_id)
      .eq('studio_id', authUser.studioId)
      .order('is_pinned', { ascending: false })
      .order('created_at', { ascending: false })
      .range(from, to)

    if (error) {
      logger.error({ err: error, clientId: client_id }, 'client notes GET failed')
      return NextResponse.json({ error: 'Failed to fetch notes' }, { status: 500 })
    }

    return NextResponse.json({
      data: data ?? [],
      meta: { total: count ?? 0, page, per_page },
    })
  } catch (err) {
    logger.error({ err }, 'client-notes GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateNoteSchema.safeParse(body)
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  try {
    const supabase = await createClient()

    // Verify client belongs to this studio
    const { data: client } = await supabase
      .from('clients')
      .select('id')
      .eq('id', parsed.data.client_id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!client) return NextResponse.json({ error: 'Client not found' }, { status: 404 })

    const { data, error } = await supabase
      .from('client_notes')
      .insert({
        ...parsed.data,
        studio_id: authUser.studioId,
        author_id: authUser.user.id,
      })
      .select('*, profiles:author_id(full_name, avatar_url)')
      .single()

    if (error) {
      logger.error({ err: error }, 'note create failed')
      return NextResponse.json({ error: 'Failed to create note' }, { status: 500 })
    }

    return NextResponse.json({ data }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'note POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { CLIENT_FILE_MIME_TYPES } from '@/lib/constants/file-types'

const ALLOWED_MIME_TYPES: readonly string[] = CLIENT_FILE_MIME_TYPES
const MAX_FILE_SIZE = 20 * 1024 * 1024 // 20 MB

const ListFilesSchema = z.object({
  client_id: z.string().uuid(),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(50).default(20),
})

const FileMetaSchema = z.object({
  client_id: z.string().uuid(),
  file_name: z.string().min(1).max(255),
  mime_type: z.enum(CLIENT_FILE_MIME_TYPES),
  kind: z.enum(['id', 'medical', 'waiver', 'health_form', 'other']).default('other'),
  expires_at: z.string().datetime().optional().nullable(),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const parsed = ListFilesSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  const { client_id, page, per_page } = parsed.data
  const from = (page - 1) * per_page
  const to = from + per_page - 1

  try {
    const supabase = await createClient()

    const { data, error, count } = await supabase
      .from('client_files')
      .select('*', { count: 'exact' })
      .eq('client_id', client_id)
      .eq('studio_id', authUser.studioId)
      .order('created_at', { ascending: false })
      .range(from, to)

    if (error) {
      logger.error({ err: error, clientId: client_id }, 'client files GET failed')
      return NextResponse.json({ error: 'Failed to fetch files' }, { status: 500 })
    }

    // Generate 1-hour signed URLs for each file so the client never exposes raw storage paths
    const filesWithUrls = await Promise.all(
      (data ?? []).map(async (f) => {
        const { data: signed, error: signError } = await supabase.storage
          .from('client-files')
          .createSignedUrl(f.storage_path, 3600)

        if (signError || !signed) {
          logger.warn({ err: signError, fileId: f.id }, 'signed URL generation failed for list item')
          return { ...f, signed_url: null }
        }
        return { ...f, signed_url: signed.signedUrl }
      })
    )

    return NextResponse.json({
      data: filesWithUrls,
      meta: { total: count ?? 0, page, per_page },
    })
  } catch (err) {
    logger.error({ err }, 'client-files GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const formData = await request.formData()
    const file = formData.get('file') as File | null
    const metaRaw = formData.get('meta') as string | null

    if (!file) return NextResponse.json({ error: 'No file provided' }, { status: 400 })
    if (!metaRaw) return NextResponse.json({ error: 'No metadata provided' }, { status: 400 })

    // Validate file
    if (file.size > MAX_FILE_SIZE) {
      return NextResponse.json({ error: 'File must be under 20 MB' }, { status: 400 })
    }
    if (!ALLOWED_MIME_TYPES.includes(file.type)) {
      return NextResponse.json({ error: 'File type not allowed. Use PDF, JPEG, PNG, or HEIC.' }, { status: 400 })
    }

    // Validate metadata
    let meta: unknown
    try {
      meta = JSON.parse(metaRaw)
    } catch {
      return NextResponse.json({ error: 'Invalid metadata JSON' }, { status: 400 })
    }

    const parsed = FileMetaSchema.safeParse(meta)
    if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

    const { client_id, file_name, mime_type, kind, expires_at } = parsed.data

    const supabase = await createClient()

    // Verify client belongs to studio
    const { data: client } = await supabase
      .from('clients')
      .select('id')
      .eq('id', client_id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!client) return NextResponse.json({ error: 'Client not found' }, { status: 404 })

    // Build storage path: {studio_id}/{client_id}/{uuid}.ext
    const ext = file_name.split('.').pop() ?? 'bin'
    const uuid = crypto.randomUUID()
    const storagePath = `${authUser.studioId}/${client_id}/${uuid}.${ext}`

    // Upload to Supabase Storage
    const fileBuffer = await file.arrayBuffer()
    const { error: uploadError } = await supabase.storage
      .from('client-files')
      .upload(storagePath, fileBuffer, {
        contentType: mime_type,
        upsert: false,
      })

    if (uploadError) {
      logger.error({ err: uploadError }, 'client file storage upload failed')
      return NextResponse.json({ error: 'Failed to upload file' }, { status: 500 })
    }

    // Insert DB record
    const { data, error } = await supabase
      .from('client_files')
      .insert({
        studio_id: authUser.studioId,
        client_id,
        storage_path: storagePath,
        file_name,
        mime_type,
        size_bytes: file.size,
        kind,
        uploaded_by: authUser.user.id,
        expires_at: expires_at ?? null,
      })
      .select()
      .single()

    if (error) {
      // Clean up the uploaded file if DB insert fails
      await supabase.storage.from('client-files').remove([storagePath])
      logger.error({ err: error }, 'client file DB insert failed')
      return NextResponse.json({ error: 'Failed to save file record' }, { status: 500 })
    }

    return NextResponse.json({ data }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'client-files POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

