import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface RouteContext {
  params: Promise<{ id: string }>
}

// Runtime schema for the get_client_profile RPC response.
// RPC defined in: supabase/migrations/20260415000005_client_crm.sql (line ~570)
// If the RPC shape drifts this parse will throw early, surfacing the mismatch
// in server logs before it reaches the client as a silent null/undefined bug.
const ClientProfileSchema = z.object({
  id: z.string().uuid(),
  studio_id: z.string().uuid(),
  first_name: z.string(),
  last_name: z.string().nullable(),
  email: z.string().nullable(),
  phone: z.string().nullable(),
  date_of_birth: z.string().nullable(),
  address: z.unknown().nullable(),
  source: z.string().nullable(),
  referral_source: z.string().nullable(),
  tags: z.array(z.string()).nullable(),
  notes: z.string().nullable(),
  preferred_contact: z.enum(['email', 'sms', 'phone', 'whatsapp']).nullable(),
  consent_minor: z.boolean(),
  archived_at: z.string().nullable(),
  total_sessions: z.number().int(),
  total_spent_cents: z.number().int(),
  lifetime_value_cents: z.number().int(),
  avg_session_value_cents: z.number().int(),
  no_show_count: z.number().int(),
  cancellation_count: z.number().int(),
  loyalty_points: z.number().int(),
  last_visit_at: z.string().nullable(),
  pinned_notes: z.array(z.object({
    id: z.string().uuid(),
    category: z.string(),
    body: z.string(),
    is_pinned: z.boolean(),
    author_id: z.string().uuid().nullable(),
    created_at: z.string(),
  })),
  consent_preferences: z.object({
    marketing_email: z.boolean(),
    marketing_sms: z.boolean(),
    transactional_only: z.boolean(),
    photo_use_portfolio: z.boolean(),
    photo_use_social: z.boolean(),
    data_retention_years: z.number().int(),
    consent_version: z.number().int(),
    consented_at: z.string().nullable(),
  }).nullable(),
  booking_count: z.number().int(),
  photo_count: z.number().int(),
  file_count: z.number().int(),
  created_at: z.string(),
  updated_at: z.string(),
})

export type ClientProfile = z.infer<typeof ClientProfileSchema>

export async function GET(_request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { id } = await params

  try {
    const supabase = await createClient()
    const { data, error } = await supabase.rpc('get_client_profile', { p_client_id: id })

    if (error) {
      logger.error({ err: error, clientId: id }, 'get_client_profile RPC failed')
      return NextResponse.json({ error: 'Failed to fetch client profile' }, { status: 500 })
    }

    if (!data) {
      return NextResponse.json({ error: 'Client not found' }, { status: 404 })
    }

    // RPC returns jsonb — check for error keys in the payload
    const payload = data as Record<string, unknown>
    if (payload.error === 'not_found') {
      return NextResponse.json({ error: 'Client not found' }, { status: 404 })
    }
    if (payload.error === 'unauthenticated') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Runtime parse: validates RPC shape matches our type contract.
    // If the RPC is modified and this parse fails, the error surfaces in logs
    // immediately rather than as a silent downstream null-access.
    const profile = ClientProfileSchema.safeParse(data)
    if (!profile.success) {
      logger.error({ err: profile.error, clientId: id }, 'get_client_profile RPC shape mismatch')
      return NextResponse.json({ error: 'Failed to fetch client profile' }, { status: 500 })
    }

    return NextResponse.json({ data: profile.data })
  } catch (err) {
    logger.error({ err }, 'client profile GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

